-- Kayak Rush 3D: 5 scenarios + 60 characters (plan 2026-10-26)
insert into public.game_scenarios (id, game, seq, title, inspiration, story, setting, stages, class_plan, asset_ids,
  rounds, minutes_per_round, character_count, active, plan_version)
select e->>0, 'kayak_rush', (e->>1)::smallint, e->>2, e->>3, e->>4, e->>5, e->6, e->7,
  array(select jsonb_array_elements_text(e->8)), 6, 5, 12, true, 2
from jsonb_array_elements($j$[["kayak-01",1,"Giải Đua Sông Ngọc","File mục I.1 (đua lách gỗ xoay, quái cây, tăng tốc khi trả lời đúng) + gói thế giới sông chung.","Giải Đua Kayak Sông Ngọc mùa hè khai mạc, cô bình luận viên Vân Anh giới thiệu từng đội trên loa. Đường đua dài sáu chặng: bến xuất phát, khúc gỗ xoay, rừng lau, ghềnh đá, cầu treo và đích đến dưới cổng hoa. Mỗi cổng phao mang một câu hỏi, đội trả lời đúng sẽ bật Nitro lướt như bay. Giữa chặng, khúc gỗ khổng lồ trôi xoay chặn ngang sông, chỉ đội đọc đúng biển báo mới tìm ra lạch tắt. Về đích, đội vô địch nhận Mái Chèo Vàng và được chèo vòng danh dự quanh hồ.","Sông xanh ngọc uốn qua rừng thông và bãi sỏi, nắng sáng, cờ đua hai bên bờ, khán giả đứng trên cầu gỗ. Nước trong thấy đá cuội. Phao cứu sinh trắng xanh treo dọc bến, đàn bồ câu đậu trên lan can cầu. Tay chèo Nắng đứng chỉ đường ở bến, khoác áo phao cam.",[{"n":1,"title":"Bến xuất phát","minutes":5,"optional":false,"goal":"Khởi động, nhận kayak và mái chèo; xuất phát.","beats":["Đèn xuất phát đỏ - vàng - xanh.","Câu đúng trước đèn xanh = xuất phát sớm 1 giây.","Trọng tài chỉ vào phao cứu sinh ở bến: ai đọc đúng tên đồ an toàn thì được xuất phát trước.","Tay chèo Nắng vẫy cờ xuất phát: đọc đúng khẩu lệnh thì được xuống nước trước."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Nitro đầu tiên.","vocab":["ready","start","paddle","go","lifebuoy","pigeon","paddler"],"assets":["kayak_boat","kayak_paddle","kayak_lifejacket","river_dock","camp_bunting","river_buoy","river_birds","char_sunny_boy"],"subtitles":[{"en":"Wear your life jacket and hold your paddle tight! We are about to start.","vi":"Mặc áo phao, nắm chắc mái chèo! Chúng ta sắp xuất phát.","parts":["Mặc áo phao, nắm chắc ",["paddle","mái chèo",1],"! Chúng ta sắp ",["start","xuất phát",0],"."]},{"en":"All the paddlers are ready. Go!","vi":"Mọi tay chèo đã sẵn sàng. Chèo đi!","parts":["Mọi ",["paddler","tay chèo",2]," đã ",["ready","sẵn sàng",0],". ",["Go","Chèo đi",0],"!"]}]},{"n":2,"title":"Khúc gỗ xoay","minutes":5,"optional":false,"goal":"Lách qua khúc gỗ xoay giữa dòng.","beats":["Gỗ xoay theo nhịp; Nitro đúng lúc thì lướt qua."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Qua chặng không mất tốc.","vocab":["log","spin","dodge","left","right"],"assets":["kayak_log_spinning","river_driftwood","river_log_fallen"],"subtitles":[{"en":"The log is spinning! Dodge to the left.","vi":"Khúc gỗ đang xoay! Né sang bên trái.","parts":["Khúc ",["log","gỗ",1]," đang ",["spin","xoay",1],"! ",["Dodge","Né",2]," sang bên ",["left","trái",0],"."]},{"en":"Quick, now dodge to the right!","vi":"Nhanh lên, giờ né sang bên phải!","parts":["Nhanh lên, giờ né sang bên ",["right","phải",0],"!"]}]},{"n":3,"title":"Rừng lau","minutes":5,"optional":false,"goal":"Đi qua rừng lau rậm, tìm lạch tắt theo biển báo.","beats":["Biển báo tiếng Anh chỉ lạch tắt.","Đi sai lạch: vòng xa thêm 5 giây."],"question_hook":"Câu hỏi trên biển báo lạch; câu hướng đi.","reward":"Lạch tắt.","vocab":["shortcut","sign","reed","narrow"],"assets":["river_reed","river_sign","river_lilypad"],"subtitles":[{"en":"Follow the sign to find a shortcut through the reeds.","vi":"Đi theo biển báo để tìm đường tắt qua rừng lau.","parts":["Đi theo ",["sign","biển báo",1]," để tìm ",["shortcut","đường tắt",2]," qua rừng ",["reed","lau",2],"."]},{"en":"This channel is very narrow, so paddle slowly.","vi":"Lạch này rất hẹp, chèo chậm thôi.","parts":["Lạch này rất ",["narrow","hẹp",2],", chèo chậm thôi."]}]},{"n":4,"title":"Ghềnh đá","minutes":5,"optional":false,"goal":"Vượt ghềnh nước trắng, tránh đá ngầm.","beats":["Đá ngầm hiện vệt bọt trắng.","Sai 2 câu liền: kayak xoay một vòng."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật. Câu ngắn 8 giây vì nước chảy nhanh.","reward":"Siêu Nitro nếu đúng 3 câu liền.","vocab":["rapids","rock","splash","careful"],"assets":["river_rock_large","river_rock_medium","water_foam"],"subtitles":[{"en":"Rapids ahead! Watch out for hidden rocks.","vi":"Ghềnh nước phía trước! Coi chừng đá ngầm.","parts":[["Rapids","Ghềnh nước",2]," phía trước! Coi chừng ",["rock","đá",0]," ngầm."]},{"en":"The water splashes up, so be careful!","vi":"Nước bắn tung tóe, hãy thật cẩn thận!","parts":["Nước ",["splash","bắn tung tóe",2],", hãy thật ",["careful","cẩn thận",1],"!"]}]},{"n":5,"title":"Cầu treo","minutes":5,"optional":false,"goal":"Lướt dưới cầu treo, khán giả cổ vũ.","beats":["Khán giả ném hoa xuống nước khi đội trả lời đúng."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Nitro cổ vũ.","vocab":["bridge","cheer","crowd","faster"],"assets":["river_bridge","river_birds","camp_bunting"],"subtitles":[{"en":"Under the hanging bridge, the crowd cheers!","vi":"Dưới cầu treo, khán giả reo hò!","parts":["Dưới ",["bridge","cầu",1]," treo, khán giả ",["cheer","reo hò",1],"!"]},{"en":"The crowd shouts, Faster!","vi":"Đông người xem hét to: nhanh hơn!","parts":["Đông ",["crowd","người xem",2]," hét to: ",["faster","nhanh hơn",2],"!"]}]},{"n":6,"title":"Cổng hoa về đích","minutes":5,"optional":false,"goal":"Nước rút cuối, về đích dưới cổng hoa.","beats":["100 m cuối: mọi câu đúng là Nitro gấp đôi.","Trao Mái Chèo Vàng, MVP là người nhiều Nitro nhất.","Hai phao cứu sinh làm cổng phụ ở vạch đích; qua đúng giữa hai phao là cộng Nitro."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Mái Chèo Vàng.","vocab":["finish","win","champion","medal","finish line"],"assets":["kayak_finish_arch","river_dock","anim_cheer","river_buoy"],"subtitles":[{"en":"The finish line is right ahead, and the first to cross it wins!","vi":"Vạch đích ở ngay trước mặt, về nhất là thắng!","parts":["Vạch ",["finish line","đích",3]," ở ngay trước mặt, về nhất là ",["win","thắng",1],"!"]},{"en":"A champion deserves a medal.","vi":"Một nhà vô địch xứng đáng nhận huy chương.","parts":["Một ",["champion","nhà vô địch",2]," xứng đáng nhận ",["medal","huy chương",2],"."]}]},{"n":7,"title":"Chặng phụ: Vòng danh dự","minutes":5,"optional":true,"goal":"Kéo dài: chèo vòng danh dự quanh hồ.","beats":["Câu ôn nhanh."],"question_hook":"Câu hỏi hiện trên cổng phao như chặng chính; đúng là Nitro. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["lap","honor"],"assets":["kayak_boat"],"subtitles":[{"en":"One lap of honor around the lake for both teams.","vi":"Một vòng danh dự quanh hồ cho cả hai đội.","parts":["Một ",["lap","vòng",1]," ",["honor","danh dự",3]," quanh hồ cho cả hai đội."]}]},{"n":8,"title":"Chặng phụ: Phỏng vấn sau đua","minutes":5,"optional":true,"goal":"Trả lời phỏng vấn tiếng Anh của cô Vân Anh.","beats":["Câu trả lời hay phát trên loa."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm biển ở bến. Câu nói/viết, không tính thua.","reward":"Huy hiệu \"Tay Chèo Sông Ngọc\".","vocab":["feel","happy","thanks"],"assets":["river_sign"],"subtitles":[{"en":"Miss Van Anh asks, How do you feel? I feel very happy!","vi":"Cô Vân Anh hỏi: Em thấy sao? Em cảm thấy rất vui!","parts":["Cô Vân Anh hỏi: Em thấy sao? Em ",["feel","cảm thấy",1]," rất ",["happy","vui",0],"!"]}]}],{},["anim_cheer","camp_bunting","char_sunny_boy","kayak_boat","kayak_finish_arch","kayak_lifejacket","kayak_log_spinning","kayak_paddle","river_birds","river_bridge","river_buoy","river_dock","river_driftwood","river_lilypad","river_log_fallen","river_reed","river_rock_large","river_rock_medium","river_sign","water_foam"]],["kayak-02",2,"Vượt Ghềnh Thác Đá","Đua lách chướng ngại; gói sông chung với ghềnh đá và thác.","Huấn luyện viên Mạnh chọn đội kayak giỏi nhất trại cho chặng đua \"Ghềnh Thác Đá\", đường đua khó nhất vùng. Ba bậc thác nhỏ, những khúc ghềnh xoáy và hang đá thấp đòi hỏi tay chèo phải phản xạ thật nhanh. Mỗi khúc ghềnh có cổng an toàn đánh dấu bằng phao, trả lời đúng mới mở được cổng. Giữa đường, một cây thông đổ chắn ngang sông, các đội phải hợp sức đẩy cây sang bên. Đội về đích đầy đủ và an toàn nhất sẽ nhận Huy hiệu Thác Đá.","Sông núi dốc, nhiều ghềnh trắng xóa, vách đá rêu xanh, thác nhỏ ba bậc. Trời nắng, bụi nước tạo cầu vồng. Thác cao đổ xuống hồ xanh, bụi nước phủ cầu vồng; phao cứu sinh cam buộc vào cọc ở mỗi bến.",[{"n":1,"title":"Kiểm tra an toàn","minutes":5,"optional":false,"goal":"Kiểm tra mũ, áo phao, mái chèo trước khi xuống ghềnh.","beats":["Mỗi món an toàn là một câu hỏi.","Khám phao cứu sinh và áo phao: mỗi món đúng tên là một dấu kiểm."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Bộ đồ an toàn đầy đủ.","vocab":["helmet","safety","check","ready","life jacket","lifebuoy"],"assets":["kayak_lifejacket","kayak_paddle","kayak_boat","river_buoy"],"subtitles":[{"en":"Put on your helmet and life jacket.","vi":"Đội mũ bảo hiểm và mặc áo phao.","parts":["Đội ",["helmet","mũ bảo hiểm",2]," và mặc ",["life jacket","áo phao",3],"."]},{"en":"Safety comes first: check your paddle again.","vi":"An toàn là trên hết: kiểm tra lại mái chèo.","parts":[["Safety","An toàn",1]," là trên hết: ",["check","kiểm tra",1]," lại mái chèo."]}]},{"n":2,"title":"Ghềnh thứ nhất","minutes":5,"optional":false,"goal":"Xuống ghềnh nhẹ đầu tiên.","beats":["Sóng đẩy kayak lên xuống."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Nitro.","vocab":["wave","down","hold on"],"assets":["water_foam","river_rock_medium"],"subtitles":[{"en":"The first rapid has small waves, so hold on!","vi":"Ghềnh đầu tiên có sóng nhỏ, bám chắc nhé!","parts":["Ghềnh đầu tiên có ",["wave","sóng",1]," nhỏ, ",["hold on","bám chắc",3]," nhé!"]},{"en":"We slide down gently.","vi":"Chúng ta trượt xuống nhẹ nhàng.","parts":["Chúng ta trượt ",["down","xuống",0]," nhẹ nhàng."]}]},{"n":3,"title":"Thác ba bậc","minutes":5,"optional":false,"goal":"Trượt qua ba bậc thác nhỏ.","beats":["Mỗi bậc thác một câu 8 giây.","Dòng nước đổ từ thác tạo ba bậc; cổng phao đặt ngay trước vực nước."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Siêu Nitro nếu đúng cả 3 bậc.","vocab":["waterfall","drop","step","brave","pool"],"assets":["river_cliff","water_foam","river_waterfall","river_waterfall_pool"],"subtitles":[{"en":"Three small waterfalls: each step is a drop.","vi":"Ba bậc thác nhỏ: mỗi bậc là một cú rơi.","parts":["Ba bậc ",["waterfall","thác",2]," nhỏ: mỗi ",["step","bậc",1]," là một cú ",["drop","rơi",2],"."]},{"en":"You are so brave! Below is a calm pool.","vi":"Em thật dũng cảm! Phía dưới là một vũng nước êm.","parts":["Em thật ",["brave","dũng cảm",2],"! Phía dưới là một ",["pool","vũng nước",3]," êm."]}]},{"n":4,"title":"Cây thông đổ","minutes":5,"optional":false,"goal":"Cả lớp hợp sức đẩy cây thông chắn sông.","beats":["Thanh sức đẩy chung: mọi câu đúng của lớp đều cộng."],"question_hook":"Câu hỏi trên thân cây; câu đúng đẩy cây đi một chút.","reward":"Mở đường cho cả lớp.","vocab":["push","together","tree","block"],"assets":["river_log_fallen","river_tree_pine"],"subtitles":[{"en":"A big pine tree has fallen and blocks the river.","vi":"Một cây thông lớn đổ xuống chắn cả dòng sông.","parts":["Một ",["tree","cây",0]," thông lớn đổ xuống ",["block","chắn",2]," cả dòng sông."]},{"en":"Push together: one, two, three!","vi":"Đẩy cùng nhau nào, một, hai, ba!","parts":[["Push","Đẩy",1]," ",["together","cùng nhau",1]," nào, một, hai, ba!"]}]},{"n":5,"title":"Hang đá thấp","minutes":5,"optional":false,"goal":"Cúi thấp lướt qua hang đá.","beats":["Đèn hang chỉ sáng khi trả lời đúng."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Đường tắt hang.","vocab":["cave","low","duck","dark"],"assets":["river_cave","camp_lantern"],"subtitles":[{"en":"The cave is very low, so duck!","vi":"Hang đá rất thấp, hãy cúi xuống!","parts":[["Cave","Hang",1]," đá rất ",["low","thấp",1],", hãy ",["duck","cúi xuống",2],"!"]},{"en":"In the dark cave, you can only hear the water.","vi":"Trong hang tối, chỉ có tiếng nước chảy.","parts":["Trong hang ",["dark","tối",1],", chỉ có tiếng nước chảy."]}]},{"n":6,"title":"Về đích Thác Đá","minutes":5,"optional":false,"goal":"Khúc ghềnh cuối và vạch đích.","beats":["Huy hiệu cho đội an toàn nhất, MVP nhiều Nitro nhất."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Huy hiệu Thác Đá.","vocab":["finish","safe","proud"],"assets":["kayak_finish_arch","anim_cheer"],"subtitles":[{"en":"There is the finish line! We are safe.","vi":"Vạch đích kia rồi! Chúng ta đã an toàn.","parts":["Vạch ",["finish","đích",1]," kia rồi! Chúng ta đã ",["safe","an toàn",1],"."]},{"en":"The whole team feels so proud.","vi":"Cả đội thấy thật tự hào.","parts":["Cả đội thấy thật ",["proud","tự hào",2],"."]}]},{"n":7,"title":"Chặng phụ: Xoáy nước","minutes":5,"optional":true,"goal":"Kéo dài: thoát xoáy nước.","beats":["Câu nhanh."],"question_hook":"Câu hỏi hiện trên cổng phao như chặng chính; đúng là Nitro. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["whirlpool","escape"],"assets":["water_foam"],"subtitles":[{"en":"The water turns into a whirlpool, so escape now!","vi":"Nước cuốn thành xoáy, hãy thoát ngay!","parts":["Nước cuốn thành ",["whirlpool","xoáy",3],", hãy ",["escape","thoát",3]," ngay!"]}]},{"n":8,"title":"Chặng phụ: Luật an toàn","minutes":5,"optional":true,"goal":"Viết 3 luật an toàn khi chèo kayak.","beats":["Luật dán ở bến."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm biển ở bến. Câu viết, không tính thua.","reward":"Huy hiệu \"Tay Chèo An Toàn\".","vocab":["always","never","wear"],"assets":["river_sign"],"subtitles":[{"en":"Rule one: always wear your life jacket.","vi":"Luật một: luôn luôn mặc áo phao.","parts":["Luật một: ",["always","luôn luôn",2]," ",["wear","mặc",1]," áo phao."]}]}],{},["anim_cheer","camp_lantern","kayak_boat","kayak_finish_arch","kayak_lifejacket","kayak_paddle","river_buoy","river_cave","river_cliff","river_log_fallen","river_rock_medium","river_sign","river_tree_pine","river_waterfall","river_waterfall_pool","water_foam"]],["kayak-03",3,"Đua Hoàng Hôn Qua Hẻm Núi","Gói sông chung, HDRI hoàng hôn; đua đội qua hẻm núi.","Cuộc đua đặc biệt chỉ diễn ra mỗi năm một lần: chèo qua Hẻm Núi Đỏ trước khi mặt trời lặn hẳn. Cô Ánh Dương đặt sáu đèn hiệu dọc hẻm núi, đội nào thắp đủ đèn khi qua sẽ được tính thời gian ưu tiên. Hẻm núi có tiếng vọng, và những câu hỏi được hỏi bằng tiếng vọng từ vách đá. Gần cuối, một đàn dơi bay ra làm tối cả lòng hẻm, các đội phải nhờ đèn hiệu để đi tiếp. Đội về đích đúng lúc mặt trời chạm núi sẽ được chụp ảnh với hoàng hôn rực rỡ.","Hẻm núi đá đỏ, sông hẹp uốn khúc, mặt trời lặn nhuộm cam vách đá. Chim bay về tổ, gió mát, bóng đổ dài. Dãy núi xa phủ sương cam phía cuối hẻm.",[{"n":1,"title":"Cửa hẻm núi","minutes":5,"optional":false,"goal":"Xuất phát ở cửa hẻm, nhận đèn hiệu.","beats":["Đèn hiệu đầu tiên thắp bằng câu đúng.","Thung lũng núi xa hiện ra làm mốc: đội nào gọi đúng tên mốc thì biết mình đi đúng hướng."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Đèn hiệu 1.","vocab":["canyon","sunset","light","valley","mountain"],"assets":["kayak_boat","river_cliff","hdri_sunset","backdrop_mountain_valley"],"subtitles":[{"en":"The canyon entrance glows at sunset.","vi":"Cửa hẻm núi sáng rực lúc hoàng hôn.","parts":["Cửa ",["canyon","hẻm núi",2]," sáng rực lúc ",["sunset","hoàng hôn",2],"."]},{"en":"Tall mountains rise on both sides as you paddle into the valley with your signal light.","vi":"Hai bên là núi cao, em cầm đèn hiệu chèo vào thung lũng.","parts":["Hai bên là ",["mountain","núi",1]," cao, em cầm đèn hiệu chèo vào ",["valley","thung lũng",3],"."]}]},{"n":2,"title":"Tiếng vọng","minutes":5,"optional":false,"goal":"Nghe câu hỏi vọng lại từ vách đá.","beats":["Câu nghe ngắn."],"question_hook":"Câu nghe hiểu; trả lời trước khi tiếng vọng tắt.","reward":"Nitro.","vocab":["echo","listen","repeat"],"assets":["river_cliff"],"subtitles":[{"en":"An echo comes from the cliff, so listen.","vi":"Có tiếng vọng từ vách đá, hãy lắng nghe.","parts":["Có tiếng ",["echo","vọng",2]," từ vách đá, hãy ",["listen","lắng nghe",1],"."]},{"en":"Then repeat the question correctly.","vi":"Rồi nhắc lại câu hỏi cho đúng.","parts":["Rồi ",["repeat","nhắc lại",2]," câu hỏi cho đúng."]}]},{"n":3,"title":"Khúc cua gắt","minutes":5,"optional":false,"goal":"Ôm cua gắt giữa hẻm.","beats":["Câu hướng trái phải."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Nitro cua.","vocab":["turn","sharp","left","right"],"assets":["river_rock_large"],"subtitles":[{"en":"A sharp turn! Go left, then right.","vi":"Một khúc cua gắt! Bẻ trái rồi phải.","parts":["Một khúc cua ",["sharp","gắt",2],"! Bẻ ",["left","trái",0]," rồi ",["right","phải",0],"."]}]},{"n":4,"title":"Đèn hiệu giữa hẻm","minutes":5,"optional":false,"goal":"Thắp 3 đèn hiệu giữa hẻm.","beats":["Mỗi đèn một câu."],"question_hook":"Câu hỏi trên đèn hiệu.","reward":"Thời gian ưu tiên.","vocab":["beacon","fire","three"],"assets":["camp_lantern","fx_fire"],"subtitles":[{"en":"Light the three beacons in the canyon.","vi":"Thắp ba đèn hiệu giữa hẻm.","parts":["Thắp ba ",["beacon","đèn hiệu",3]," giữa hẻm."]},{"en":"You need three correct answers to light them all.","vi":"Em cần đúng ba câu để thắp đủ lửa.","parts":["Em cần đúng ",["three","ba",0]," câu để thắp đủ lửa."]}]},{"n":5,"title":"Đàn dơi","minutes":5,"optional":false,"goal":"Đàn dơi làm tối lòng hẻm; đi theo ánh đèn hiệu.","beats":["Đèn đã thắp soi đường."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Qua bóng tối.","vocab":["bat","dark","follow"],"assets":["camp_lantern","river_birds"],"subtitles":[{"en":"The bats make the canyon very dark.","vi":"Đàn dơi làm hẻm thật tối.","parts":["Đàn ",["bat","dơi",1]," làm hẻm thật ",["dark","tối",1],"."]},{"en":"Follow the beacon light.","vi":"Hãy đi theo ánh đèn hiệu nhé.","parts":["Hãy ",["follow","đi theo",1]," ánh đèn hiệu nhé."]}]},{"n":6,"title":"Mặt trời chạm núi","minutes":5,"optional":false,"goal":"Nước rút cuối về đích.","beats":["Ảnh hoàng hôn cho đội về đích."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Danh hiệu \"Tay Chèo Hoàng Hôn\".","vocab":["finish","golden","photo"],"assets":["kayak_finish_arch","hdri_sunset","anim_cheer"],"subtitles":[{"en":"Golden light shines on the water as you reach the finish.","vi":"Ánh vàng chiếu lên mặt nước khi em về đích.","parts":["Ánh ",["golden","vàng",2]," chiếu lên mặt nước khi em về ",["finish","đích",1],"."]},{"en":"A beautiful photo to remember forever.","vi":"Một bức ảnh đẹp để nhớ mãi.","parts":["Một bức ",["photo","ảnh",1]," đẹp để nhớ mãi."]}]},{"n":7,"title":"Chặng phụ: Sao đầu tiên","minutes":5,"optional":true,"goal":"Kéo dài: đua dưới ngôi sao đầu tiên.","beats":["Câu nhanh."],"question_hook":"Câu hỏi hiện trên cổng phao như chặng chính; đúng là Nitro. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["first star","evening"],"assets":["hdri_night"],"subtitles":[{"en":"The first star appears in the evening sky.","vi":"Ngôi sao đầu tiên hiện lên trong buổi chiều tối.","parts":[["First star","Ngôi sao đầu tiên",2]," hiện lên trong buổi ",["evening","chiều tối",2],"."]}]},{"n":8,"title":"Chặng phụ: Tả hoàng hôn","minutes":5,"optional":true,"goal":"Viết 2 câu tả hoàng hôn.","beats":["Câu hay in lên ảnh."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm biển ở bến. Câu viết, không tính thua.","reward":"Huy hiệu \"Hẻm Núi Đỏ\".","vocab":["orange","beautiful","sky"],"assets":["hdri_sunset"],"subtitles":[{"en":"The sky is orange and so beautiful.","vi":"Bầu trời màu cam thật đẹp.","parts":["Bầu trời màu ",["orange","cam",1]," thật ",["beautiful","đẹp",1],"."]}]}],{},["anim_cheer","backdrop_mountain_valley","camp_lantern","fx_fire","hdri_night","hdri_sunset","kayak_boat","kayak_finish_arch","river_birds","river_cliff","river_rock_large"]],["kayak-04",4,"Tiếp Sức Đội Kayak","Đua đội (teams.ts); gói sông chung với nhiều trạm bến.","Ngày hội làng chài có cuộc đua tiếp sức kayak: mỗi đội chia người chèo các chặng, trao mái chèo tại bến tiếp sức. Bác trưởng làng Sáu Hòa nói đội mạnh không phải đội có một người giỏi, mà là đội ai cũng góp sức. Mỗi lần trao mái chèo là một câu hỏi chung của đội, trả lời đúng thì người sau xuất phát với Nitro. Giữa cuộc đua, chợ nổi chắn ngang sông, các đội phải lách qua những chiếc ghe bán trái cây. Đội về đích được làng tặng giỏ trái cây và vòng hoa.","Sông rộng chảy qua làng chài, bốn trạm bến tiếp sức dọc bờ, mỗi trạm treo cờ màu đội. Buổi sáng mát, nhiều người dân ra xem. Thuyền chèo của dân chài neo dọc bến, bồ câu bay trên mái đình làng, giỏ đan bày ở chợ nổi. Dân làng dắt ngựa ra bến, bạn trẻ trượt ván dọc chợ nổi.",[{"n":1,"title":"Chia chặng","minutes":5,"optional":false,"goal":"Đội chia người cho từng chặng tiếp sức.","beats":["Mỗi người chọn chặng hợp sức mình.","Hai bạn trẻ trao gậy tiếp sức: mỗi câu đúng là một lần trao gậy."],"question_hook":"Câu hỏi chung của đội ở bến.","reward":"Đội hình.","vocab":["team","relay","turn","baton"],"assets":["river_dock","camp_bunting","kayak_boat","char_skater_boy","char_boy_1"],"subtitles":[{"en":"The team divides the legs of the relay.","vi":"Cả đội chia nhau từng chặng của cuộc tiếp sức.","parts":["Cả ",["team","đội",1]," chia nhau từng chặng của cuộc ",["relay","tiếp sức",2],"."]},{"en":"Whoever has a turn takes the baton.","vi":"Mỗi người đến lượt sẽ nhận gậy tiếp sức.","parts":["Mỗi người đến ",["turn","lượt",2]," sẽ nhận ",["baton","gậy tiếp sức",4],"."]}]},{"n":2,"title":"Chặng 1: Bến làng","minutes":5,"optional":false,"goal":"Người thứ nhất xuất phát.","beats":["Trao mái chèo ở bến 2.","Chuyền cờ tiếp sức giữa kayak và thuyền chèo của bác chài.","Ngựa nâu của làng kéo thuyền qua bến cạn: đọc đúng tên mới đi tiếp."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Nitro trao gậy.","vocab":["pass","next","quick","rowboat","pigeon","horse","village"],"assets":["kayak_paddle","river_dock","river_birds","river_boat_row","village_horse_a"],"subtitles":[{"en":"Leg one at the village dock: pass the baton to the next teammate!","vi":"Chặng một ở bến làng: chuyền gậy cho bạn kế tiếp!","parts":["Chặng một ở bến ",["village","làng",1],": ",["pass","chuyền",2]," gậy cho bạn ",["next","kế tiếp",2],"!"]},{"en":"You must be very quick!","vi":"Phải thật nhanh nhé!","parts":["Phải thật ",["quick","nhanh",1]," nhé!"]}]},{"n":3,"title":"Chặng 2: Chợ nổi","minutes":5,"optional":false,"goal":"Lách qua ghe chợ nổi.","beats":["Ghe trái cây di chuyển chậm.","Chợ nổi: kayak lách qua thuyền chèo chất đầy giỏ đan, mỗi món đọc đúng tên là mở lối."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Đường lách.","vocab":["market","boat","fruit","avoid","basket","rowboat"],"assets":["river_boat_row","food_apple","fish_basket","river_buoy"],"subtitles":[{"en":"At the floating market, avoid every boat.","vi":"Ở chợ nổi, hãy tránh mọi ghe.","parts":["Ở chợ nổi, hãy ",["avoid","tránh",2]," mọi ",["boat","ghe",0],"."]},{"en":"The fruit seller waves at you.","vi":"Cô bán trái cây vẫy chào em.","parts":["Cô bán ",["fruit","trái cây",1]," vẫy chào em."]}]},{"n":4,"title":"Chặng 3: Cầu làng","minutes":5,"optional":false,"goal":"Lướt dưới cầu làng, dân làng cổ vũ.","beats":["Câu đúng = tiếng trống cổ vũ, Nitro.","Ngựa trắng đứng chờ ở đầu cầu làng, nhìn các kayak lách qua."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Nitro trống.","vocab":["village","drum","cheer","bridge","horse"],"assets":["river_bridge","village_horse_b"],"subtitles":[{"en":"The villagers play drums and cheer!","vi":"Dân làng đánh trống và cổ vũ!","parts":["Dân ",["village","làng",1]," đánh ",["drum","trống",1]," và ",["cheer","cổ vũ",1],"!"]},{"en":"Paddling under the bridge is so much fun.","vi":"Chèo dưới cầu thật vui.","parts":["Chèo dưới ",["bridge","cầu",1]," thật vui."]}]},{"n":5,"title":"Chặng 4: Đồng sen","minutes":5,"optional":false,"goal":"Đi qua đồng sen, tránh lá sen lớn.","beats":["Lá sen làm chậm kayak."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Lạch sen.","vocab":["lotus","leaf","pink"],"assets":["river_lilypad","river_reed"],"subtitles":[{"en":"The pink lotus field: do not hit the big leaves.","vi":"Đồng sen hồng, đừng đụng lá lớn.","parts":["Đồng ",["lotus","sen",2]," hồng, đừng đụng ",["leaf","lá",1]," lớn."]},{"en":"Paddle slowly past every pink flower.","vi":"Chèo thật chậm qua từng bông hồng.","parts":["Chèo thật chậm qua từng bông ",["pink","hồng",1],"."]}]},{"n":6,"title":"Về đích ngày hội","minutes":5,"optional":false,"goal":"Người cuối về đích, cả đội ăn mừng.","beats":["Giỏ trái cây và vòng hoa."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Cúp Tiếp Sức.","vocab":["together","finish","celebrate"],"assets":["kayak_finish_arch","anim_cheer"],"subtitles":[{"en":"The whole team crosses the finish together!","vi":"Cả đội cùng nhau về đích!","parts":["Cả đội ",["together","cùng nhau",1]," về ",["finish","đích",1],"!"]},{"en":"Let us celebrate the festival!","vi":"Hãy ăn mừng ngày hội nào!","parts":["Hãy ",["celebrate","ăn mừng",3]," ngày hội nào!"]}]},{"n":7,"title":"Chặng phụ: Chặng bù","minutes":5,"optional":true,"goal":"Kéo dài: chặng thêm cho đội muốn gỡ.","beats":["Câu nhanh."],"question_hook":"Câu hỏi hiện trên cổng phao như chặng chính; đúng là Nitro. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["extra","chance"],"assets":["kayak_boat"],"subtitles":[{"en":"An extra leg to catch up: you still have a chance!","vi":"Thêm một chặng bù để gỡ lại, còn cơ hội!","parts":["Thêm một chặng ",["extra","bù",2]," để gỡ lại, còn ",["chance","cơ hội",2],"!"]}]},{"n":8,"title":"Chặng phụ: Lời cảm ơn","minutes":5,"optional":true,"goal":"Viết lời cảm ơn đồng đội.","beats":["Thẻ cảm ơn trao tay."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm biển ở bến. Câu viết, không tính thua.","reward":"Huy hiệu \"Đồng Đội Vàng\".","vocab":["thank you","helpful","friend"],"assets":["river_sign"],"subtitles":[{"en":"Thank you, friend, for helping the team.","vi":"Cảm ơn